package companion

const auditPageStyle = `<style>
.audit-page{max-width:1190px;margin:0 auto}.audit-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.audit-stat{padding:18px 20px;border:1px solid var(--border);border-radius:11px;background:var(--surface)}.audit-stat span{display:block;color:var(--muted);font-size:11px;font-weight:650}.audit-stat strong{display:block;margin-top:8px;font-size:25px;font-weight:750;line-height:1}.audit-stat small{display:block;margin-top:7px;color:var(--quiet);font-size:10.5px}.audit-stat.hit strong{color:var(--danger)}.audit-stat.fallback strong{color:#b0752c}
.audit-toolbar{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;margin-bottom:17px}.audit-toolbar .field{flex:1 1 190px}.audit-toolbar .field span{font-size:11px;color:var(--muted);font-weight:650}.audit-toolbar .button{flex:none}.audit-table{min-width:940px}.audit-table .mono{font-size:10.5px}.audit-result{display:inline-flex;padding:3px 7px;border-radius:6px;background:#e7f3eb;color:#087753;font-size:10px;font-weight:700}.audit-result.hit{background:#f9e9e6;color:#ad493a}.audit-source{color:var(--muted);font-size:10.5px}.audit-user-name{display:block;font-size:11.5px;font-weight:700}.audit-user-meta{display:block;margin-top:3px}.audit-preview{display:block;max-width:190px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}.audit-mobile{display:none}.audit-pages{display:flex;justify-content:flex-end;align-items:center;gap:9px;margin-top:15px;color:var(--muted);font-size:11px}.audit-pages a{padding:6px 9px;border:1px solid var(--border-strong);border-radius:7px;text-decoration:none}.audit-empty{padding:36px 10px;text-align:center;color:var(--muted);font-size:12px}.audit-note{margin:15px 0 0;color:var(--quiet);font-size:11px}
.audit-dialog{width:min(670px,calc(100vw - 30px));max-height:calc(100dvh - 30px);padding:0;border:1px solid var(--border-strong);border-radius:13px;background:var(--bg);color:var(--text);box-shadow:0 24px 70px rgba(30,27,24,.23)}.audit-dialog::backdrop{background:rgba(32,30,27,.47)}.audit-dialog-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;padding:18px 21px;border-bottom:1px solid var(--border);background:var(--surface)}.audit-dialog-head h2{margin:0;font-size:17px}.audit-dialog-head p{margin:4px 0 0;color:var(--muted);font-size:11px}.audit-close{width:29px;height:29px;border:0;border-radius:6px;background:var(--bg);font-size:20px;line-height:1}.audit-dialog-body{max-height:calc(100dvh - 168px);padding:20px 21px;overflow-y:auto;scrollbar-width:thin}.audit-dialog-foot{display:flex;justify-content:flex-end;gap:9px;padding:13px 21px;border-top:1px solid var(--border);background:var(--surface)}.audit-setting-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.audit-setting-grid .field{min-width:0}.audit-setting-grid .wide{grid-column:1/-1}.audit-setting-grid .field>span{font-size:11px;font-weight:700}.audit-setting-grid .field small{color:var(--muted);font-size:10.5px;line-height:1.5}.audit-check{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:650}.audit-check input{accent-color:var(--text)}.audit-section-title{margin:22px 0 5px;font-size:13px}.audit-section-help{margin:0 0 12px;color:var(--muted);font-size:11px}.audit-thresholds{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.audit-threshold{display:grid;gap:6px;padding:11px;border:1px solid var(--border);border-radius:8px;background:var(--surface)}.audit-threshold span{font:600 11px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.audit-threshold small{color:var(--muted);font-size:10px}.audit-threshold input{min-height:33px}.audit-keywords{min-height:88px;resize:vertical}.audit-input-text{max-height:min(55vh,480px);margin:0;padding:14px;border:1px solid var(--border);border-radius:8px;background:#fff;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace}.audit-detail-meta{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:13px;color:var(--muted);font-size:11px}.audit-toast{position:fixed;top:19px;left:50%;z-index:2147483647;transform:translateX(-50%);padding:10px 15px;border:1px solid #b8d9c3;border-radius:9px;background:#edf8f0;color:#16633e;box-shadow:0 12px 30px rgba(0,0,0,.12);font-size:12px;font-weight:700}.audit-toast.error{border-color:#e7b7ae;background:#fff0ed;color:#a73e31}
.audit-endpoint-list{min-width:0}.audit-endpoint-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:2px 0 10px}.audit-endpoint-heading strong{font-size:12px}.audit-endpoint-heading small{display:block;margin-top:3px;color:var(--muted);font-size:10.5px}.audit-endpoint{margin:0 0 9px;padding:12px;border:1px solid var(--border);border-radius:9px;background:var(--surface)}.audit-endpoint-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}.audit-endpoint-top strong{font-size:11px}.audit-endpoint-top>div{display:flex;gap:5px}.audit-endpoint-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.audit-endpoint-grid .wide{grid-column:1/-1}.audit-endpoint-grid .field{min-width:0}.audit-row-actions{display:flex;gap:5px;flex-wrap:wrap}.audit-row-actions .button{white-space:nowrap}#audit-settings{overflow:hidden}#audit-settings-form{display:flex;flex-direction:column;max-height:calc(100dvh - 32px)}#audit-settings .audit-dialog-head,#audit-settings .audit-dialog-foot{flex:none}#audit-settings .audit-dialog-body{min-height:0;max-height:none}
@media(max-width:900px){.audit-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.audit-thresholds{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:720px){.audit-table-wrap{display:none}.audit-mobile{display:grid;gap:9px}.audit-card{padding:13px;border:1px solid var(--border);border-radius:9px;background:var(--bg)}.audit-card-top,.audit-card-bottom{display:flex;justify-content:space-between;gap:12px}.audit-card-top{align-items:center}.audit-card p{margin:8px 0;color:var(--muted);font-size:11px}.audit-card-bottom{align-items:center;color:var(--muted);font-size:10.5px}.audit-dialog-body{padding:15px}.audit-setting-grid{grid-template-columns:1fr}.audit-setting-grid .wide{grid-column:auto}.audit-thresholds{grid-template-columns:1fr 1fr}}
@media(max-width:430px){.audit-endpoint-grid{grid-template-columns:1fr}.audit-endpoint-grid .wide{grid-column:auto}.audit-stats{gap:8px}.audit-stat{padding:14px}.audit-stat strong{font-size:21px}.audit-thresholds{grid-template-columns:1fr}}
</style>`

const auditPageScript = `<script>
document.querySelectorAll('[data-audit-open]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.auditOpen)?.showModal()));
document.querySelectorAll('[data-audit-close],[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog')?.close()));
document.querySelectorAll('.audit-dialog,.log-dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()}));
const auditToast=document.querySelector('.audit-toast');if(auditToast)setTimeout(()=>auditToast.remove(),3500);
const auditSettingsForm=document.getElementById('audit-settings-form');
const auditEndpointList=document.getElementById('audit-endpoints');
function refreshAuditEndpoints(){if(!auditEndpointList)return;const rows=[...auditEndpointList.querySelectorAll('[data-endpoint]')];document.getElementById('audit-endpoint-count').value=rows.length;rows.forEach((row,index)=>{row.querySelectorAll('[data-endpoint-field]').forEach(field=>field.name='endpoint_'+index+'_'+field.dataset.endpointField);const name=row.querySelector('[data-endpoint-field="name"]').value.trim();row.querySelector('[data-endpoint-title]').textContent='接口 '+(index+1)+(name?' · '+name:'');row.querySelector('[data-audit-move="up"]').disabled=index===0;row.querySelector('[data-audit-move="down"]').disabled=index===rows.length-1;row.querySelector('[data-audit-remove]').disabled=rows.length===1});document.querySelector('[data-add-endpoint]').disabled=rows.length>=5}
document.querySelector('[data-add-endpoint]')?.addEventListener('click',()=>{if(auditEndpointList.children.length>=5)return;const row=document.getElementById('audit-endpoint-template').content.firstElementChild.cloneNode(true);row.querySelector('[data-endpoint-field="name"]').value='备用接口 '+auditEndpointList.children.length;auditEndpointList.appendChild(row);refreshAuditEndpoints();row.scrollIntoView({block:'nearest',behavior:'smooth'})});
auditEndpointList?.addEventListener('click',event=>{const row=event.target.closest('[data-endpoint]');if(!row)return;if(event.target.closest('[data-audit-remove]')){if(auditEndpointList.children.length>1){row.remove();refreshAuditEndpoints()}return}const move=event.target.closest('[data-audit-move]');if(!move)return;if(move.dataset.auditMove==='up'&&row.previousElementSibling)auditEndpointList.insertBefore(row,row.previousElementSibling);if(move.dataset.auditMove==='down'&&row.nextElementSibling)auditEndpointList.insertBefore(row.nextElementSibling,row);refreshAuditEndpoints()});
auditEndpointList?.addEventListener('input',event=>{if(event.target.matches('[data-endpoint-field="name"]'))refreshAuditEndpoints()});refreshAuditEndpoints();

function showAuditError(message){document.querySelector('.audit-toast')?.remove();const toast=document.createElement('div');toast.className='audit-toast error';toast.setAttribute('role','alert');toast.textContent=message;document.getElementById('audit-settings').appendChild(toast);setTimeout(()=>toast.remove(),4500)}
auditSettingsForm?.addEventListener('submit',async event=>{event.preventDefault();refreshAuditEndpoints();const submit=auditSettingsForm.querySelector('[type=submit]');submit.disabled=true;try{const response=await fetch(auditSettingsForm.action,{method:'POST',body:new URLSearchParams(new FormData(auditSettingsForm)),credentials:'same-origin',headers:{Accept:'application/json'}});if(response.redirected){location.assign('/login');return}const result=(response.headers.get('content-type')||'').includes('application/json')?await response.json():{error:response.status===403?'请求未通过验证，请刷新页面重试':'服务器响应异常，请稍后重试'};if(!response.ok){showAuditError(result.error||'保存审计设置失败');return}location.assign('/audit?saved=1')}catch(_){showAuditError('网络连接失败，请稍后重试')}finally{submit.disabled=false}});
</script>`

const auditPageTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>内容审计 · CPA Companion</title>` + pageStyle + usageLogStyle + auditPageStyle + `</head><body><div class="shell"><aside class="sidebar"><a class="brand" href="/keys"><img class="brand-mark" src="/assets/logo.png" width="30" height="30" alt=""><span class="brand-copy"><span class="brand-title">CPA Companion</span>` + brandVersionTemplate + `</span></a><nav class="nav"><span class="nav-label">工作台</span><a class="nav-link" href="/dashboard">仪表盘</a><a class="nav-link" href="/keys">我的密钥</a><a class="nav-link" href="/admin">分流方案</a><a class="nav-link active" aria-current="page" href="/audit">内容审计</a><a class="nav-link" href="/prices">模型价格</a><a class="nav-link" href="/logs">使用日志</a></nav>` + sidebarGitHubTemplate + `<div class="sidebar-footer"><div class="identity"><span class="avatar"><span class="avatar-fallback">C</span>{{if .User.AvatarURL}}<img src="{{.User.AvatarURL}}" alt="" referrerpolicy="no-referrer">{{end}}</span><span class="identity-copy"><span class="identity-name">{{.User.Username}}</span><span class="identity-meta">{{.User.ID}}</span></span></div><form method="post" action="/auth/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout">退出登录</button></form></div></aside><main class="content"><div class="audit-page"><header class="page-head"><div><h1>内容审计</h1><p>随机抽查用户输入；每个可识别会话的首条请求必检。命中风险阈值或上游 cyber_policy 标记时保存对话上下文。</p></div><button class="button" type="button" data-audit-open="audit-settings">审计设置</button></header>
<div class="audit-stats"><section class="audit-stat"><span>TypeSafe 抽查</span><strong>{{if .Config.Enabled}}已启用{{else}}未启用{{end}}</strong><small>抽查比例 {{.Config.SamplePercent}}% · 上游标记始终记录</small></section><section class="audit-stat"><span>审计记录数</span><strong>{{.Summary.Checked}}</strong><small>含抽查与上游命中标记</small></section><section class="audit-stat hit"><span>命中记录</span><strong>{{.Summary.Hits}}</strong><small>保存命中请求的文本对话</small></section><section class="audit-stat fallback"><span>关键词回退</span><strong>{{.Summary.Fallbacks}}</strong><small>SystemOne 超时或失败时使用</small></section></div>
<section class="surface surface-pad"><div class="surface-head"><div><h2 class="surface-title">审计记录</h2><p class="surface-description">未命中仅保存元数据；命中记录可查看用户与助手的历史文本。</p></div><span class="status {{if not .Config.Enabled}}waiting{{end}}">{{if .Config.Enabled}}抽查中{{else}}仅上游标记{{end}}</span></div><form class="audit-toolbar" action="/audit" method="get"><label class="field"><span>用户 ID</span><input class="input" name="user" value="{{.UserFilter}}" placeholder="精确用户 ID"></label><label class="field"><span>结果</span><select name="result"><option value="" {{if not .ResultFilter}}selected{{end}}>全部结果</option><option value="hit" {{if eq .ResultFilter "hit"}}selected{{end}}>命中</option><option value="clear" {{if eq .ResultFilter "clear"}}selected{{end}}>未命中</option><option value="fallback" {{if eq .ResultFilter "fallback"}}selected{{end}}>关键词回退</option></select></label><button class="button secondary" type="submit">查询</button><a class="button secondary" href="/audit">重置</a></form>
{{if .Rows}}<div class="audit-table-wrap"><table class="audit-table"><thead><tr><th>时间</th><th>用户名 / ID / API Key</th><th>模型 / 路径</th><th>触发原因</th><th>审计来源</th><th>结果</th><th>类别 / 分数</th><th>耗时</th><th>操作</th></tr></thead><tbody>{{range .Rows}}<tr><td class="mono">{{.AtText}}</td><td><strong class="audit-user-name">{{.Username}}</strong><span class="audit-source audit-user-meta mono">ID {{.UserID}}</span><span class="audit-source audit-user-meta mono">Key {{.KeyID}}</span></td><td><span class="mono">{{.Model}}</span><br><span class="audit-source">{{.Route}}</span></td><td>{{.ReasonText}}</td><td>{{.SourceText}}{{if gt .AttemptCount 1}}<br><span class="audit-source">尝试 {{.AttemptCount}} 个接口</span>{{end}}</td><td><span class="audit-result {{if .Hit}}hit{{end}}">{{.ResultText}}</span></td><td>{{if .Category}}<span class="mono">{{.Category}}</span><br><span class="audit-source">{{.ScoreText}}{{if .ThresholdPercent}} / 阈值 {{.ThresholdPercent}}%{{end}}</span>{{else}}—{{end}}</td><td class="mono">{{.DurationMS}} ms</td><td><div class="audit-row-actions">{{if .Hit}}<button class="button secondary small" type="button" data-audit-open="audit-record-{{.ID}}">查看上下文</button>{{end}}{{if index $.LinkedLogIDs .UsageLogID}}<button class="button secondary small" type="button" data-audit-open="log-detail-{{.UsageLogID}}">使用日志</button>{{end}}{{if not (or .Hit (index $.LinkedLogIDs .UsageLogID))}}—{{end}}</div></td></tr>{{end}}</tbody></table></div><div class="audit-mobile">{{range .Rows}}<article class="audit-card"><div class="audit-card-top"><strong>{{.Username}}</strong><span class="audit-result {{if .Hit}}hit{{end}}">{{.ResultText}}</span></div><p>ID {{.UserID}} · Key {{.KeyID}}<br>{{.Model}} · {{.Category}} · {{.SourceText}}<br>{{.AtText}} · {{.ReasonText}}</p><div class="audit-card-bottom"><span>{{.ScoreText}} · {{.DurationMS}} ms</span>{{if .Hit}}<button class="button secondary small" type="button" data-audit-open="audit-record-{{.ID}}">查看上下文</button>{{end}}{{if index $.LinkedLogIDs .UsageLogID}}<button class="button secondary small" type="button" data-audit-open="log-detail-{{.UsageLogID}}">使用日志</button>{{end}}</div></article>{{end}}</div>{{else}}<div class="audit-empty">暂无审计记录。TypeSafe 抽查和 OpenAI 上游标记的结果会显示在这里。</div>{{end}}<div class="audit-pages">{{if gt .Page 1}}<a href="{{.PreviousURL}}">‹ 上一页</a>{{end}}<span>第 {{.Page}} 页</span>{{if .HasNext}}<a href="{{.NextURL}}">下一页 ›</a>{{end}}</div></section><p class="audit-note">仅管理员可访问本页。命中记录的对话文本保存在本机 SQLite 数据库中，请按敏感数据管理备份。</p></div></main></div>
<dialog class="audit-dialog" id="audit-settings" aria-labelledby="audit-settings-title"><form id="audit-settings-form" method="post" action="/admin/audit"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="audit-dialog-head"><div><h2 id="audit-settings-title">审计设置</h2><p>使用 TypeSafe/Jev 决策；超时或失败时按关键词回退。</p></div><button class="audit-close" type="button" data-audit-close aria-label="关闭">×</button></div><div class="audit-dialog-body"><div class="audit-setting-grid"><label class="audit-check wide"><input type="checkbox" name="enabled" {{if .Config.Enabled}}checked{{end}}>启用内容审计</label><div class="audit-endpoint-list wide"><div class="audit-endpoint-heading"><div><strong>审计接口</strong><small>按列表顺序尝试；单个接口失败、超时或限流时切换。全部失败才使用关键词回退。</small></div><button class="button secondary small" type="button" data-add-endpoint>添加接口</button></div><input type="hidden" id="audit-endpoint-count" name="endpoint_count" value="{{len .Endpoints}}"><div id="audit-endpoints">{{range .Endpoints}}<section class="audit-endpoint" data-endpoint><div class="audit-endpoint-top"><strong data-endpoint-title>接口 {{.Name}}</strong><div><button class="button secondary small" type="button" data-audit-move="up" aria-label="上移">↑</button><button class="button secondary small" type="button" data-audit-move="down" aria-label="下移">↓</button><button class="button secondary small" type="button" data-audit-remove>删除</button></div></div><input type="hidden" name="endpoint_{{.Index}}_id" data-endpoint-field="id" value="{{.ID}}"><div class="audit-endpoint-grid"><label class="field"><span>名称</span><input class="input" type="text" name="endpoint_{{.Index}}_name" data-endpoint-field="name" value="{{.Name}}" maxlength="64" required></label><label class="field"><span>模型名称</span><input class="input" type="text" name="endpoint_{{.Index}}_model" data-endpoint-field="model" value="{{.Model}}" maxlength="128" required></label><label class="field wide"><span>完整审计接口地址</span><input class="input" type="url" name="endpoint_{{.Index}}_base_url" data-endpoint-field="base_url" value="{{.BaseURL}}" required><small>填写含 /systemone 或 /v1/decisions 等路径的完整 POST URL；不会自动拼接。</small></label><label class="field wide"><span>API Key</span><input class="input" type="password" name="endpoint_{{.Index}}_api_key" data-endpoint-field="api_key" autocomplete="new-password" placeholder="{{if .KeyConfigured}}已配置，留空保持不变{{else}}填写此接口的密钥{{end}}" {{if not .KeyConfigured}}required{{end}}></label>{{if .KeyConfigured}}<label class="audit-check wide"><input type="checkbox" name="endpoint_{{.Index}}_clear_key" data-endpoint-field="clear_key">清除已保存的密钥</label>{{end}}</div></section>{{end}}</div></div><label class="field"><span>随机抽查比例（%）</span><input class="input" type="number" name="sample_percent" min="0" max="100" step="1" value="{{.Config.SamplePercent}}" required><small>0 仍会检查每个可识别会话的首条请求。</small></label><label class="field"><span>单接口超时（毫秒）</span><input class="input" type="number" name="timeout_ms" min="500" max="10000" step="100" value="{{.Config.TimeoutMS}}" required><small>单个接口超时后尝试下一个，全部失败才使用关键词规则。</small></label></div><template id="audit-endpoint-template"><section class="audit-endpoint" data-endpoint><div class="audit-endpoint-top"><strong data-endpoint-title>新接口</strong><div><button class="button secondary small" type="button" data-audit-move="up" aria-label="上移">↑</button><button class="button secondary small" type="button" data-audit-move="down" aria-label="下移">↓</button><button class="button secondary small" type="button" data-audit-remove>删除</button></div></div><input type="hidden" data-endpoint-field="id" value=""><div class="audit-endpoint-grid"><label class="field"><span>名称</span><input class="input" type="text" data-endpoint-field="name" maxlength="64" required></label><label class="field"><span>模型名称</span><input class="input" type="text" data-endpoint-field="model" value="jev-latest" maxlength="128" required></label><label class="field wide"><span>完整审计接口地址</span><input class="input" type="url" data-endpoint-field="base_url" value="https://ai-gateway.vercel.sh/typesafe/v1/systemone" required><small>填写含 /systemone 或 /v1/decisions 等路径的完整 POST URL；不会自动拼接。</small></label><label class="field wide"><span>API Key</span><input class="input" type="password" data-endpoint-field="api_key" autocomplete="new-password" placeholder="填写此接口的密钥" required></label></div></section></template><h3 class="audit-section-title">风险阈值</h3><p class="audit-section-help">各类别分数达到阈值时，记录本次用户输入。</p><div class="audit-thresholds">{{range .Categories}}<label class="audit-threshold"><span>{{.Name}}</span><small>参考默认值 {{.Default}}%</small><input class="input" type="number" name="threshold_{{.Name}}" min="0" max="100" step="1" value="{{.Value}}" required></label>{{end}}</div><h3 class="audit-section-title">关键词回退</h3><p class="audit-section-help">SystemOne 超时或失败时使用；每行一个词，不区分大小写。</p><textarea class="input audit-keywords" name="keywords" maxlength="8100" placeholder="每行一个关键词">{{.KeywordsText}}</textarea></div><div class="audit-dialog-foot"><button class="button secondary" type="button" data-audit-close>取消</button><button class="button" type="submit">保存审计设置</button></div></form></dialog>
{{range .Rows}}{{if .Hit}}<dialog class="audit-dialog" id="audit-record-{{.ID}}"><div class="audit-dialog-head"><div><h2>命中上下文 · #{{.ID}}</h2><p>{{.AtText}} · {{.Username}} · ID {{.UserID}}</p></div><button class="audit-close" type="button" data-audit-close aria-label="关闭">×</button></div><div class="audit-dialog-body"><div class="audit-detail-meta"><span>{{.Model}}</span><span>{{.Category}}</span><span>{{.SourceText}}</span><span>{{.ScoreText}}</span></div><pre class="audit-input-text">{{if .InputText}}{{.InputText}}{{else}}（此请求没有可提取的对话文本）{{end}}</pre></div><div class="audit-dialog-foot"><button class="button secondary" type="button" data-audit-close>关闭</button></div></dialog>{{end}}{{end}}{{range .LinkedLogs}}` + usageLogDetailTemplate + `{{end}}{{if .Saved}}<div class="audit-toast" role="status">审计设置已保存</div>{{end}}` + selectControlScript + auditPageScript + navigationScript + `</body></html>`
